public static class R1Oracle
{
    public const string Claim = "forall";
    public const bool Exhaustive = false;
    public const bool Checked = true;
    public static bool Hyp(ulong x) => x >= 4294967296UL;
    public static bool Prop(ulong x) => x - 1 < x;
    public static bool HypO(object?[] a) => Hyp((ulong)a[0]!);
    public static bool HasBody => false;
    public static object? BodyO(object?[] a) => null;
    public static bool PropO(object?[] a, object? r) => Prop((ulong)a[0]!);
